import os

import sqlite_utils

DB_PATH = os.environ.get("SLOTS_DB", "slots.db")

SEED = [
    {"who": "Dana", "when_at": "2026-02-01T10:00", "confirmed": 1},
    {"who": "Rae", "when_at": "2026-02-01T11:00", "confirmed": 0},
]


